import java.util.List;

/**
 * Assembles the MHPCO premium for the items of a quote.
 *
 * <p>Knows that a premium is the policy base premium plus the risk surcharges
 * the insured items carry plus the processing fee charged on every premium;
 * defers what the items of a quote are tariffed at to the policy base premium,
 * and knows nothing about JSON or the command line.
 */
final class PremiumCalculator {

    private static final int PROCESSING_FEE_IN_G = 5;

    private PremiumCalculator() {
    }

    static int premiumFor(List<Item> items) {
        return PolicyBasePremium.of(items) + RiskSurcharges.of(items) + PROCESSING_FEE_IN_G;
    }
}
